    def test_list_empty(self, repo):
        assert list(repo.list()) == []

    def test_list_multiple(self, repo):
        repo.add(_make_task(id=1, title="A"))
        repo.add(_make_task(id=2, title="B"))
        result = list(repo.list())
        assert len(result) == 2
        assert result[0].id == 1
        assert result[1].id == 2


class TestSqliteUpdate:
    def test_update_fields(self, repo):
        repo.add(_make_task())
        task = repo.get(1)
        task.title = "Updated"
        task.status = TaskStatus.DONE
        task.completed_at = datetime(2025, 6, 1, 12, 0, 0, tzinfo=timezone.utc)
        repo.update(task)
        got = repo.get(1)
        assert got.title == "Updated"
        assert got.status == TaskStatus.DONE
        assert got.completed_at is not None

    def test_update_tags(self, repo):
        repo.add(_make_task(tags=[Tag("old")]))
        task = repo.get(1)
        task.tags = [Tag("new"), Tag("extra")]
        repo.update(task)
        got = repo.get(1)
        assert set(t.name for t in got.tags) == {"new", "extra"}

    def test_update_nonexistent_raises(self, repo):
        with pytest.raises(KeyError):
            repo.update(_make_task(id=999))


class TestSqliteDelete:
    def test_delete_existing(self, repo):
        repo.add(_make_task())
        assert repo.delete(1) is True
        assert repo.get(1) is None

    def test_delete_missing(self, repo):
        assert repo.delete(999) is False


class TestSqliteNextId:
    def test_empty_db(self, repo):
        assert repo.next_id() == 1

    def test_after_inserts(self, repo):
        repo.add(_make_task(id=5))
        assert repo.next_id() == 6


class TestSqliteDueAt:
    def test_due_at_persists(self, repo):
        due = datetime(2025, 12, 31, 23, 59, 0, tzinfo=timezone.utc)
        repo.add(_make_task(due_at=due))
        got = repo.get(1)
        assert got.due_at == due

    def test_due_at_none(self, repo):
        repo.add(_make_task(due_at=None))
        got = repo.get(1)
        assert got.due_at is None

