        assert page.has_more is True

    def test_offset_past_end(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=10, offset=100), NOW)
        assert len(page.items) == 0
        assert page.has_more is False

    def test_last_page(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=2, offset=2), NOW)
        assert len(page.items) == 2
        assert page.has_more is False

"""Tests for SqliteTaskRepository against an in-memory connection."""

from datetime import datetime, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.repository_sqlite import SqliteTaskRepository


@pytest.fixture()
def repo():
    return SqliteTaskRepository.in_memory()


def _make_task(id=1, title="Test", tags=None, due_at=None, priority=TaskPriority.MEDIUM):
    return Task(
        id=id,
        title=title,
        status=TaskStatus.PENDING,
        priority=priority,
        due_at=due_at,
        created_at=datetime(2025, 1, 1, 0, 0, 0, tzinfo=timezone.utc),
        tags=tags or [],
    )


class TestSqliteAddAndGet:
    def test_round_trip(self, repo):
        task = _make_task(tags=[Tag("work")])
        repo.add(task)
        got = repo.get(1)
        assert got is not None
        assert got.id == 1
        assert got.title == "Test"
        assert got.tags == [Tag("work")]

    def test_add_duplicate_raises(self, repo):
        repo.add(_make_task())
        with pytest.raises(ValueError, match="already exists"):
            repo.add(_make_task())

    def test_get_missing(self, repo):
        assert repo.get(999) is None


class TestSqliteList:
    def test_list_empty(self, repo):
        assert list(repo.list()) == []

    def test_list_multiple(self, repo):
        repo.add(_make_task(id=1, title="A"))
        repo.add(_make_task(id=2, title="B"))
        result = list(repo.list())
        assert len(result) == 2
        assert result[0].id == 1
        assert result[1].id == 2


class TestSqliteUpdate:
    def test_update_fields(self, repo):
        repo.add(_make_task())
        task = repo.get(1)
        task.title = "Updated"
        task.status = TaskStatus.DONE
        task.completed_at = datetime(2025, 6, 1, 12, 0, 0, tzinfo=timezone.utc)
        repo.update(task)
        got = repo.get(1)
        assert got.title == "Updated"
        assert got.status == TaskStatus.DONE
        assert got.completed_at is not None

    def test_update_tags(self, repo):
        repo.add(_make_task(tags=[Tag("old")]))
        task = repo.get(1)
        task.tags = [Tag("new"), Tag("extra")]
        repo.update(task)
        got = repo.get(1)
        assert set(t.name for t in got.tags) == {"new", "extra"}

    def test_update_nonexistent_raises(self, repo):
        with pytest.raises(KeyError):
            repo.update(_make_task(id=999))


class TestSqliteDelete:
    def test_delete_existing(self, repo):
        repo.add(_make_task())
        assert repo.delete(1) is True
        assert repo.get(1) is None

    def test_delete_missing(self, repo):
        assert repo.delete(999) is False


class TestSqliteNextId:
